#!/usr/bin/env bash
set -euo pipefail
# Fix: restore blank ranges + specials never wipe range + rare labels as Other answers

if [[ ! -f package.json ]] || [[ ! -d src/lib ]]; then
  echo "ERROR: cd into automated-psychometric first."
  exit 1
fi

echo "→ Branch p2c4-words-grok"
git fetch origin 2>/dev/null || true
git switch p2c4-words 2>/dev/null || git checkout p2c4-words
git pull 2>/dev/null || true
if git show-ref --verify --quiet refs/heads/p2c4-words-grok; then
  git switch p2c4-words-grok
else
  git switch -c p2c4-words-grok
fi

export GROK_PAYLOAD=''
python3 - <<'PY'
import base64, gzip, json, os, pathlib
payload = json.loads(base64.b64decode(os.environ["GROK_PAYLOAD"]))
root = pathlib.Path(".")
for rel, blob in payload["files"].items():
    path = root / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(blob))
    print("  wrote", rel)
config = root / "src/components/ConfigScreen.tsx"
config.write_bytes(gzip.decompress(base64.b64decode(payload["config_gz_b64"])))
print("  wrote src/components/ConfigScreen.tsx")
print("OK")
PY

git add src/lib/responseScaleAnswers.ts src/lib/responseScaleState.ts src/components/ConfigScreen.tsx
git status --short
echo ""
echo "Next:"
echo "  git commit -m \"fix: recover blank ranges; specials never wipe scale\""
echo "  npm run dev"
echo "Then hard-refresh the browser (Ctrl+Shift+R)."
echo "If scale still blank: open the ... menu → Reset to detected"
